            Q('e3', L('Che cosa controllare prima di usare un’immagine generata in un prodotto?', 'What to check before using a generated image in a product?'), [L('Le condizioni d’uso dello strumento', 'The tool’s terms of use'), L('Il colore dominante', 'The dominant colour'), L('Niente', 'Nothing'), L('La risoluzione dello schermo', 'Screen resolution')], 0, L('Uso commerciale e proprietà.', 'Commercial use and ownership.')),
        ], task('text', L('Scrivi una breve dichiarazione da mettere sotto un’immagine generata con l’AI per un articolo, che citi lo **strumento** e che l’immagine è **generata**.', 'Write a short caption to put under an AI-generated image in an article, naming the **tool** and stating the image is **generated**.'), '', [re('generat|creat[ao] con|made with|created with', L('Dichiari che è generata', 'You state it is generated')), re('\bAI\b|\bIA\b|intelligenza artificiale|artificial intelligence|Midjourney|Firefly|DALL|Stable Diffusion|Flux|Gemini|ChatGPT', L('Citi lo strumento o l’AI', 'You name the tool or AI'))], '', 'Immagine generata con l’intelligenza artificiale (Adobe Firefly), a scopo illustrativo.'), [
            dMatch(pMatch(), [['C2PA', L('Standard per le Content Credentials', 'Standard for Content Credentials')], ['SynthID', L('Filigrana invisibile', 'Invisible watermark')], ['Deepfake', L('Falso realistico di persone', 'Realistic fake of people')], ['AI Act', L('Obbligo di dichiarare i contenuti artificiali', 'Duty to disclose artificial content')]], L('Trasparenza nei media.', 'Transparency in media.')),
            dFlash(pFlash(), [[L('Conviene leggere le condizioni d’uso prima dell’uso commerciale', 'Reading the terms before commercial use is wise'), true], [L('Si possono creare deepfake di persone reali liberamente', 'Deepfakes of real people can be made freely'), false], [L('Esistono filigrane invisibili per i contenuti AI', 'There are invisible watermarks for AI content'), true], [L('Ogni immagine generata è protetta da copyright', 'Every generated image is copyrighted'), false]], L('Creare con responsabilità.', 'Creating responsibly.')),
        ]),
        lesson('editing', L('Modificare e rifinire', 'Editing and refining'), [
            P('Raramente la prima immagine è quella giusta. L’**inpainting** rigenera solo una zona scelta (un oggetto da togliere, una mano da correggere); l’**outpainting** allarga l’immagine oltre i bordi; l’**upscaling** aumenta la risoluzione per la stampa.', 'The first image is rarely the right one. **Inpainting** regenerates only a chosen area (an object to remove, a hand to fix); **outpainting** extends the image beyond its edges; **upscaling** raises the resolution for print.'),
            Fig(L(fig_genmedia_edit('it'), fig_genmedia_edit('en')),
                L('Tre esempi sulla stessa immagine di montagne. Inpainting: un’area tratteggiata in rosa viene rigenerata con un oggetto nuovo. Outpainting: intorno all’immagine una cornice tratteggiata più grande viene riempita continuando le montagne. Upscaling: una versione piccola e quadrettata diventa una versione grande e nitida.', 'Three examples on the same mountain picture. Inpainting: an area dashed in pink is regenerated with a new object. Outpainting: a larger dashed frame around the picture is filled by continuing the mountains. Upscaling: a small blocky version becomes a large sharp one.'),
                L('Tre ritocchi diversi: dentro, fuori, più grande.', 'Three different touch-ups: inside, outside, bigger.')),
            P('Per una serie coerente (lo stesso personaggio in più scene) usa un’**immagine di riferimento** e descrizioni ripetute uguali. Cambia **una cosa alla volta** tra un tentativo e l’altro: così capisci quale parola ha fatto la differenza.', 'For a consistent series (the same character in several scenes) use a **reference image** and repeat the same descriptions. Change **one thing at a time** between attempts: that way you see which word made the difference.'),
        ], [
            Q('ed1', L('Che cosa fa l’inpainting?', 'What does inpainting do?'), [L('Rigenera solo una zona scelta', 'Regenerates only a chosen area'), L('Allarga l’immagine', 'Extends the image'), L('Aumenta la risoluzione', 'Raises the resolution'), L('Toglie i metadati', 'Removes metadata')], 0, L('Ritocchi mirati.', 'Targeted touch-ups.')),
            Q('ed2', L('Che cosa fa l’upscaling?', 'What does upscaling do?'), [L('Aumenta la risoluzione', 'Raises the resolution'), L('Cambia lo stile', 'Changes the style'), L('Aggiunge oggetti', 'Adds objects'), L('Riduce i colori', 'Reduces colours')], 0, L('Utile per la stampa.', 'Useful for print.')),
            Q('ed3', L('Come capisci quale parola conta nel prompt?', 'How do you find which word matters in the prompt?'), [L('Cambiando una cosa alla volta', 'By changing one thing at a time'), L('Cambiando tutto ogni volta', 'By changing everything each time'), L('Scrivendo in maiuscolo', 'By writing in capitals'), L('Non si può', 'You cannot')], 0, L('Come un esperimento.', 'Like an experiment.')),
        ], task('text', L('Abbina in tre righe `inpainting:`, `outpainting:` e `upscaling:` a ciò che fanno.', 'Match in three lines `inpainting:`, `outpainting:` and `upscaling:` to what they do.'), '', [re('^inpainting\s*:.*(zona|area|parte|part)', L('Inpainting giusto', 'Inpainting right')), re('^outpainting\s*:.*(bord|allarg|estend|edge|extend)', L('Outpainting giusto', 'Outpainting right')), re('^upscaling\s*:.*(risoluz|resolution|grand|bigger)', L('Upscaling giusto', 'Upscaling right'))], '', "inpainting: rigenera una zona scelta\noutpainting: allarga oltre i bordi\nupscaling: aumenta la risoluzione"), [
            dMatch(pMatch(), [['Inpainting', L('Ritocca una zona', 'Retouches an area')], ['Outpainting', L('Allarga i bordi', 'Extends the edges')], ['Upscaling', L('Più risoluzione', 'More resolution')], [L('Immagine di riferimento', 'Reference image'), L('Personaggio coerente', 'Consistent character')]], L('Gli attrezzi del ritocco.', 'Editing tools.')),
            dFlash(pFlash(), [[L('Cambiare una cosa alla volta aiuta a capire', 'Changing one thing at a time helps understanding'), true], [L('La prima immagine è sempre la migliore', 'The first image is always the best'), false], [L('L’inpainting può togliere un oggetto', 'Inpainting can remove an object'), true], [L('L’upscaling cambia il soggetto', 'Upscaling changes the subject'), false]], L('Rifinire con metodo.', 'Refining with method.')),
        ]),
        lesson('detect', L('Riconoscere i contenuti generati', 'Recognising generated content'), [
            P('Non esiste un controllo infallibile, ma più indizi insieme aiutano. Cerca le **etichette**: le Content Credentials (C2PA) si leggono con strumenti di verifica online, alcune piattaforme mostrano la dicitura «creato con l’AI», e i contenuti di Google contengono SynthID. Attenzione: i metadati si perdono facilmente con uno screenshot, quindi **la loro assenza non prova nulla**.', 'There is no foolproof check, but several clues together help. Look for **labels**: Content Credentials (C2PA) can be read with online verification tools, some platforms show an “AI-generated” tag, and Google’s content carries SynthID. Beware: metadata is easily lost with a screenshot, so **its absence proves nothing**.'),
            P('Poi guarda il **contenuto**: scritte senza senso, mani e orecchie strane, ombre e riflessi incoerenti, voci senza respiro o con un ritmo innaturale. Infine il **contesto**: chi l’ha pubblicato per primo? Una ricerca inversa dell’immagine trova versioni precedenti; una notizia clamorosa dovrebbe comparire su più fonti affidabili.', 'Then look at the **content**: meaningless lettering, odd hands and ears, inconsistent shadows and reflections, voices without breaths or with an unnatural rhythm. Finally the **context**: who published it first? A reverse image search finds earlier versions; a sensational story should appear in several reliable sources.'),
            P('Le regole si fanno più severe: l’AI Act europeo impone di dichiarare i contenuti artificiali realistici, e in Italia la legge sull’intelligenza artificiale del 2025 ha introdotto un reato per chi diffonde senza consenso contenuti falsificati con l’AI che causano un danno. Se ricevi un deepfake su una persona, non condividerlo: segnalalo alla piattaforma.', 'The rules are getting stricter: the EU AI Act requires disclosing realistic artificial content, and in Italy the 2025 artificial intelligence law introduced an offence for spreading, without consent, AI-falsified content that causes harm. If you receive a deepfake of a person, do not share it: report it to the platform.'),
        ], [
            Q('dt1', L('Un’immagine senza Content Credentials è sicuramente vera?', 'Is an image without Content Credentials surely real?'), [L('Sì, i metadati non mentono', 'Yes, metadata does not lie'), L('Sì, se è in alta risoluzione', 'Yes, if it is high resolution'), L('No, i metadati si perdono facilmente', 'No, metadata is easily lost'), L('Sì, se è stata condivisa molte volte', 'Yes, if it has been shared many times')], 2, L('Basta uno screenshot.', 'A screenshot is enough.')),
            Q('dt2', L('Che cosa trova una ricerca inversa dell’immagine?', 'What does a reverse image search find?'), [L('Versioni precedenti della stessa immagine', 'Earlier versions of the same image'), L('La password di chi l’ha pubblicata', 'The password of whoever posted it'), L('Il modello usato, sempre', 'The model used, always'), L('Il prezzo della foto', 'The photo’s price')], 0, L('Utile per scoprire il contesto originale.', 'Useful to find the original context.')),
            Q('dt3', L('Che cosa fai se ricevi un deepfake su un collega?', 'What do you do if you receive a deepfake of a colleague?'), [L('Lo inoltri per avvisare tutti', 'Forward it to warn everyone'), L('Lo commenti sotto il post', 'Comment under the post'), L('Lo salvi e lo ripubblichi', 'Save it and repost it'), L('Non lo condividi e lo segnali alla piattaforma', 'Do not share it and report it to the platform')], 3, L('Diffonderlo fa danni, e può essere un reato.', 'Spreading it does harm, and can be an offence.')),
        ], task('text', L('Scrivi una checklist di tre controlli, una riga per controllo con `[ ]`: uno sulle **etichette**, uno sul **contenuto** e uno sul **contesto**.', 'Write a checklist of three checks, one line per check with `[ ]`: one on **labels**, one on **content** and one on **context**.'), "[ ] \n[ ] \n[ ] ", [re('^\[ \]\s*\S.*\n\[ \]\s*\S.*\n\[ \]\s*\S', L('Tre controlli', 'Three checks')), re('etichett|label|C2PA|credential|SynthID|metadat|filigran|watermark', L('Le etichette', 'The labels')), re('man[io]|hand|scritt|text|ombr|shadow|rifless|reflect|voc[ei]|voice|dettagl|detail', L('Il contenuto', 'The content')), re('fonte|source|ricerca inversa|reverse|chi l|who|pubblicat|posted|contest|context', L('Il contesto', 'The context'))], '', "[ ] cerco etichette o Content Credentials (C2PA) e una filigrana come SynthID\n[ ] guardo mani, scritte, ombre e riflessi\n[ ] faccio una ricerca inversa e controllo chi l’ha pubblicata per primo"), [
            dMatch(pMatch(), [[L('Etichette', 'Labels'), L('C2PA, SynthID, dicitura AI', 'C2PA, SynthID, AI tag')], [L('Contenuto', 'Content'), L('Mani, scritte, ombre', 'Hands, lettering, shadows')], [L('Contesto', 'Context'), L('Chi l’ha pubblicato per primo', 'Who posted it first')], [L('Ricerca inversa', 'Reverse search'), L('Versioni precedenti', 'Earlier versions')]], L('Tre livelli di controllo.', 'Three levels of checking.')),
            dFlash(pFlash(), [[L('Uno screenshot può cancellare i metadati', 'A screenshot can erase metadata'), true], [L('Esiste un controllo infallibile per ogni deepfake', 'There is a foolproof check for every deepfake'), false], [L('Una notizia clamorosa dovrebbe avere più fonti', 'A sensational story should have several sources'), true], [L('Condividere un deepfake per scherzo è sempre innocuo', 'Sharing a deepfake as a joke is always harmless'), false]], L('Occhio critico.', 'A critical eye.')),
        ]),
    ],
];
